'use strict';
let calmProgress={};try{const p=JSON.parse(localStorage.getItem('spotmatch-calm-v1')||'{}');if(p&&typeof p==='object'&&!Array.isArray(p))calmProgress=p;}catch{}
let calmState=null;let calmFilter='All';
function calmSave(){try{localStorage.setItem('spotmatch-calm-v1',JSON.stringify(calmProgress));}catch{}}
function calmPose(pose='mountain',seated=true){const skin='#d5ac87',ink='#355447';const head='<circle cx="120" cy="45" r="20" fill="'+skin+'"/><path d="M109 44h1m20 0h1M114 54q6 5 12 0" stroke="'+ink+'" stroke-width="2.5" fill="none" stroke-linecap="round"/>';const arms={mountain:'M99 84L86 118M141 84L154 118',reach:'M99 84L85 60L86 23M141 84L155 60L154 23',shoulders:'M99 84L83 101L94 117M141 84L157 101L146 117',wings:'M99 84L76 91L83 70M141 84L164 91L157 70',cat:'M98 85L92 116M142 85L148 116',sunshine:'M99 84L78 92L58 80M141 84L153 114',tree:'M99 84L81 73L77 50M141 84L159 73L163 50',star:'M99 84L64 92M141 84L176 92'};let body=seated?'<path d="M77 132H171M84 132V178M164 132V178M83 85V132" stroke="#8c9e83" stroke-width="6" fill="none"/><path d="M106 122L144 134V171L157 176M128 122L163 134V171L176 176" stroke="#78938b" stroke-width="15" fill="none" stroke-linecap="round"/>':'<path d="M110 122L107 175M132 122L139 175" stroke="#78938b" stroke-width="16" fill="none" stroke-linecap="round"/>';body+='<rect x="114" y="60" width="12" height="20" rx="5" fill="'+skin+'"/><path d="M102 73Q120 65 138 73L146 126H96Z" fill="#e0ab87"/>'+head+`<path d="${arms[pose]||arms.mountain}" stroke="${skin}" stroke-width="12" fill="none" stroke-linecap="round"/>`;if(pose==='shoulders')body+='<path d="M70 75q-12 10 0 20m-5-1l5 1l1-6M170 75q12 10 0 20m5-1l-5 1l-1-6" fill="none" stroke="#719081" stroke-width="2"/>';return `<svg viewBox="0 0 240 195" aria-hidden="true"><rect width="240" height="195" rx="22" fill="#f5f2e7"/><ellipse cx="120" cy="181" rx="83" ry="6" fill="#dbe5cf"/>${body}</svg>`;}
function calmArt(d){if(d.mode==='pose')return calmPose(d.pose);if(d.mode==='breath')return pictureIcon('flower');if(d.mode==='rest')return friendlyCover('stories');return pictureIcon(({find:'flower',match:'leaf',clue:'ball',rule:'butterfly',path:'bee',notice:'apple',comfort:'chair',ground:'tree',hands:'hands',routine:'basket'})[d.mode]||'flower');}
const calmLibraryBefore=libraryHome;
libraryHome=function(){calmLibraryBefore();const section=document.createElement('section');section.id='calm-garden';section.className='calm-library';const done=Object.values(calmProgress).filter(x=>x?.explored).length;section.innerHTML=`<div class="section-head"><div><span class="eyebrow">ROOM FOR A LITTLE PAUSE</span><h2>Focus, move & unwind.</h2></div><span class="micro">20 gentle activities</span></div><button class="calm-banner" id="calmOpen"><div><span class="adult-badge">Play together</span><h2>The Little Calm Garden</h2><p>Notice a detail. Move your way. Choose a comfortable pause.</p><span>${done?`${done} explored · `:''}Come and explore →</span></div><div class="calm-banner-art" aria-hidden="true">${calmPose('tree')}</div></button><p class="note">Optional focus games, relaxation choices, and yoga-inspired movements. Seated versions and watching are always welcome.</p>`;app.append(section);document.querySelector('#calmOpen').onclick=calmHome;const a=document.createElement('a');a.className='sen-shortcut';a.href='#calm-garden';a.textContent='Visit the Little Calm Garden ↓';app.querySelector('.welcome-copy')?.append(a);};
function calmNav(){document.querySelector('#libraryNav').onclick=libraryHome;document.querySelector('#brand').onclick=e=>{e.preventDefault();libraryHome();};document.querySelector('#courseNav').onclick=calmHome;document.querySelector('#guideNav').onclick=()=>{calmHome();const d=document.querySelector('#calmGuide');d.open=true;d.scrollIntoView();};}
function calmHome(){activeLearningCourse=null;senActive=null;app.innerHTML=`<div class="play-top"><button class="back" id="calmLibrary">← Our adventures</button><span class="together-note">♧ An adult joins in</span></div><section class="course-hero friendly-course-hero calm-hero"><div><span class="eyebrow">FOCUS · MOVE · UNWIND</span><h1>The Little Calm Garden</h1><p>Small moments of noticing, comfortable movement, and choice.</p><button class="primary" id="calmStart">Choose something gentle ↓</button><p class="micro">20 activities · Start anywhere · No timer or scores</p></div><div class="course-hero-art" aria-hidden="true">${calmPose('tree')}</div></section><details class="course-about" id="calmGuide"><summary><span>For grown-ups</span><span class="about-subtitle">Our goal, adaptations, movement guidance & research</span><span aria-hidden="true">＋</span></summary><div class="sen-parent-copy"><h3>What can be difficult?</h3><p>Attention changes with interest, fatigue, language demands, sensory input, movement needs, and access. Difficulty staying with an activity does not necessarily mean a child lacks concentration. Some children benefit from a quieter task, a movement break, clearer choices, or an adult’s help feeling comfortable.</p><h3>Our goal</h3><p>Offer enjoyable practice noticing relevant details and communicating a preferred pause. Gentle yoga-inspired invitations offer optional movement, not perfect poses. Looking away, moving, or declining an activity is welcome; stillness and eye contact are not goals.</p><h3>Who may find this useful?</h3><p>Children with attention, sensory, language, or developmental support needs may enjoy selected activities. Choose by the child’s preferences and access, not diagnosis. Focus games practise the tasks shown; broad improvements in attention, reading, ADHD, or autism are not established by this app.</p><h3>Adult support and movement</h3><p>Stay nearby and offer choices. Use the child’s usual stable seating and established movement supports. Follow any existing movement restrictions or therapist advice; seek individual guidance when unsure what is suitable. Never pull a limb, push a stretch, remove support, or ask the child to copy beyond a comfortable range. Stop for pain, dizziness, distress, or fatigue.</p><p>Movement stays gentle: no inversions, one-leg balance, floor transfers, breath holds, deep stretches, or fixed pose durations. Choose the seated version, imagine a movement, or simply watch. These illustrations are invitations, not an assessment of movement or a substitute for adapted instruction.</p><h3>Relaxation should be a choice</h3><p>Breathing is ordinary and self-paced. No deep breaths or eyes-closed requirement. Body or breath focus can feel unpleasant; an external picture, familiar movement, company, or ending the activity may fit better. Calm activities should never be used to suppress communication or deny a needed break.</p><h3>Research and its limits</h3><p>Research on yoga and mindfulness for children is promising but mixed. Studies vary in participants, programmes, outcomes, and quality. Evidence from a taught programme does not validate our individual games or poses, and findings from older children or adults may not apply to younger children with complex needs. These are supportive wellbeing activities, not treatment or reading interventions.</p><ul class="sen-sources"><li><a href="https://www.nccih.nih.gov/health/yoga-effectiveness-and-safety" target="_blank" rel="noopener noreferrer">NCCIH · Yoga: Effectiveness and Safety ↗</a><p>Research overview and the importance of appropriate adaptation.</p></li><li><a href="https://www.nccih.nih.gov/health/tips/things-to-know-about-mind-and-body-practices-for-children-and-teens" target="_blank" rel="noopener noreferrer">NCCIH · Mind and body practices for children and teens ↗</a><p>Parent guidance; child-specific safety research remains limited.</p></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/39717371/" target="_blank" rel="noopener noreferrer">Mind-body exercise and ADHD · Systematic review and meta-analysis (2024) ↗</a><p>Results differ across outcomes; the review did not find improvements in every domain.</p></li><li><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC11506216/" target="_blank" rel="noopener noreferrer">Mindfulness and autism · Systematic review (2024) ↗</a><p>Promising findings, varied protocols, and limited child studies.</p></li></ul><p>Our activity designs have not been evaluated. Participation and a comfortable choice matter more than finishing a course.</p></div></details><section id="calmActivities"><div class="section-head"><h2>What feels right today?</h2><span class="micro">${Object.values(calmProgress).filter(x=>x?.explored).length} explored</span></div><div class="calm-filters" role="group" aria-label="Activity type">${['All','Focus','Relax','Move','Together'].map(f=>`<button class="secondary" data-calm-filter="${f}" aria-pressed="${f===calmFilter}">${f}</button>`).join('')}</div><div class="grid friendly-game-grid">${calmActivities.map((d,i)=>calmFilter==='All'||calmFilter===d.group?`<button class="course-card" data-calm-game="${i}"><div class="thumb" style="--tint:#e6ecdd">${calmArt(d)}${calmProgress[i]?.explored?'<span class="played-mark" aria-label="Explored">✓</span>':''}</div><span class="card-num">${d.group.toUpperCase()}</span><h3>${d.title}</h3><span class="card-bottom">Explore together →</span></button>`:'').join('')}</div></section><details class="quiet-notes"><summary>Progress on this device</summary><p>Only explored activity numbers are saved locally. No feeling, diagnosis, movement quality, or concentration score is recorded. Other course progress is separate.</p><button class="secondary" id="calmReset">Clear Calm Garden progress</button></details>`;document.querySelector('#calmLibrary').onclick=libraryHome;document.querySelector('#calmStart').onclick=()=>document.querySelector('#calmActivities').scrollIntoView({behavior:'smooth'});document.querySelectorAll('[data-calm-game]').forEach(b=>b.onclick=()=>calmOpen(+b.dataset.calmGame));document.querySelectorAll('[data-calm-filter]').forEach(b=>b.onclick=()=>{calmFilter=b.dataset.calmFilter;calmHome();document.querySelector('#calmActivities').scrollIntoView();});document.querySelector('#calmReset').onclick=()=>{calmProgress={};calmSave();calmHome();};calmNav();window.scrollTo(0,0);}
function calmOpen(index){calmState={index,step:0,selected:null,found:false,help:false,fewer:false,seated:true,watch:false,path:0,breath:false,paused:false,routine:[null,null,null],message:''};calmRender();window.scrollTo(0,0);}
function calmModel(s){const mode=calmActivities[s.index].mode;const shape=s.step%2;const leaf=(value,color)=>({calmLeaf:value,color});let target,options,prompt;
 if(mode==='find'){target='flower';options=['flower','tree','apple'];prompt='Find the flower that matches our model.';}
 if(mode==='match'){target=leaf(shape,'#86a28a');options=[leaf(shape,'#d3b46e'),leaf(1-shape,'#86a28a'),leaf(1-shape,'#d3b46e')];prompt='Find the same leaf shape. Its colour can be different.';}
 if(mode==='clue'||mode==='rule'){const color=s.step%2===0;target={calmLeaf:0,color:'#86a28a'};options=color?[leaf(1,'#86a28a'),leaf(0,'#d3b46e'),leaf(1,'#d3b46e')]:[leaf(0,'#d3b46e'),leaf(1,'#86a28a'),leaf(1,'#d3b46e')];prompt=color?'Our clue is colour: find a leaf with the same colour.':'Our clue is shape: find a leaf with the same shape.';}
 if(s.fewer)options=options.slice(0,2);const offset=s.step%options.length;options=[...options.slice(offset),...options.slice(0,offset)];return{target,options,prompt,answer:(options.length-offset)%options.length};}
function calmPicture(p){if(p?.calmLeaf!==undefined)return `<svg viewBox="0 0 120 120" aria-hidden="true"><path d="${p.calmLeaf===0?'M60 15Q110 48 60 106Q10 48 60 15Z':'M60 12L72 36L100 32L89 57L108 73L77 80L60 107L43 80L12 73L31 57L20 32L48 36Z'}" fill="${p.color}" stroke="#355447" stroke-width="3"/><path d="M60 31V105" stroke="#355447" stroke-width="2"/></svg>`;return pictureIcon(p);}
function calmRender(focus){const s=calmState,d=calmActivities[s.index];let body='',inv=d.invite;
 if(['find','match','clue','rule'].includes(d.mode)){const t=calmModel(s);inv=t.prompt;body=`<div class="calm-model" aria-label="Model picture">${calmPicture(t.target)}</div><div class="learning-options calm-options">${t.options.map((p,i)=>`<button class="learning-option ${s.selected===i?'selected':''} ${s.help&&i===t.answer?'hinted':''}" data-calm-choice="${i}" aria-label="Picture ${i+1}" aria-pressed="${s.selected===i}">${calmPicture(p)}</button>`).join('')}</div><div class="calm-controls"><button class="secondary" id="calmFewer">${s.fewer?'Show three pictures':'Show two pictures'}</button><button class="secondary" id="calmHelp">A little help</button><button class="primary" id="calmCheck" ${s.selected===null?'disabled':''}>Let’s see ✓</button>${s.found?'<button class="secondary" id="calmTry">Another example →</button>':''}</div>`;}
 if(d.mode==='path'){body=`<div class="calm-path" role="group" aria-label="Three firefly homes">${['flower','tree','house'].map((id,i)=>`<button class="learning-option ${s.path===i?'hinted':''}" data-calm-home="${i}" aria-label="Home ${i+1}: ${id}" ${i!==s.path?'disabled':''}>${pictureIcon(id)}<span>${i+1}</span></button>`).join('')}</div><p>${s.path===3?'The firefly visited all three homes.':'Choose the highlighted home. There is no hurry.'}</p>${s.path===3?'<button class="secondary" id="calmPathAgain">Visit again</button>':''}`;}
 if(['notice','comfort','ground'].includes(d.mode)){const ids=d.mode==='notice'?['apple','butterfly','spoon']:d.mode==='comfort'?['chair','tree','rabbit']:['flower','book','cup'];const labels=d.mode==='comfort'?['A comfortable rest','A little movement or outside view','Company or communication']:ids.map(nameOf);body=`<div class="learning-options calm-options">${ids.map((p,i)=>`<button class="learning-option ${s.selected===i?'selected':''}" data-calm-open="${i}" aria-pressed="${s.selected===i}" aria-label="${senEscape(labels[i])}">${pictureIcon(p)}${d.mode==='comfort'?`<small>${labels[i]}</small>`:''}</button>`).join('')}</div>`;}
 if(d.mode==='breath'){body=`<div class="calm-flower ${s.breath?'open':''}">${pictureIcon('flower')}</div><p>${s.watch?'Just enjoy the picture. No breathing task.':s.paused?'Paused. Breathe normally or choose something else.':'Breathe normally. Open or close the flower whenever you like; it does not set your pace.'}</p><div class="calm-controls"><button class="secondary" id="calmWatchBreath" aria-pressed="${s.watch}">${s.watch?'Try an ordinary breath':'Just watch the picture'}</button><button class="secondary" id="calmFlower" ${s.watch||s.paused?'disabled':''}>${s.breath?'Let the flower rest':'Open the flower'}</button><button class="secondary" id="calmPause">${s.paused?'Continue if you like':'Pause'}</button></div>`;}
 if(d.mode==='hands'){body=`<div class="calm-pose-art">${pictureIcon('hands')}</div><p>${s.watch?'Imagine or watch the movement. No moving needed.':s.step%2?'Let your hands return to a comfortable resting place.':'Open your hands just a little, only if comfortable.'}</p><div class="calm-controls"><button class="secondary" id="calmHands">${s.step%2?'Explore opening':'Return to rest'}</button><button class="secondary" id="calmWatch" aria-pressed="${s.watch}">${s.watch?'Try a small movement':'Imagine or watch instead'}</button></div>`;}
 if(d.mode==='pose'){body=`<div class="calm-pose-art">${calmPose(d.pose,s.seated||d.pose==='cat')}</div><div class="calm-controls"><button class="secondary" id="calmSeat" aria-pressed="${s.seated}">${s.seated?'Seated version ✓':'Choose seated version'}</button><button class="secondary" id="calmStand" aria-pressed="${!s.seated}" ${d.pose==='cat'?'disabled':''}>Usual supported standing</button><button class="secondary" id="calmWatch" aria-pressed="${s.watch}">${s.watch?'Watching / imagining ✓':'Watch or imagine instead'}</button></div><p>${s.watch?'Watching or imagining is a complete choice. There is no need to move.':senEscape(s.seated?d.seated:d.standing)}</p><p class="micro">Keep your usual supports. No perfect pose or hold is needed. Stop if uncomfortable.</p>`;}
 if(d.mode==='rest'){body=`<div class="calm-pose-art">${calmPose('mountain')}</div><p>Nothing to complete. Rest, move a little, look around, or finish.</p>`;}
 if(d.mode==='routine'){const sets=[['flower','leaf'],['chair','star'],['book','rabbit']],labels=[['A little looking','Notice a detail'],['Rest or watch','A gentle movement'],['A familiar book','Company or a pause']];body=`<div class="calm-routine">${sets.map((ids,row)=>`<fieldset><legend>${['A focus choice','Move, watch, or rest','A comfortable ending'][row]}</legend>${ids.map((id,i)=>`<button class="secondary ${s.routine[row]===i?'selected':''}" data-calm-routine="${row}:${i}" aria-pressed="${s.routine[row]===i}">${pictureIcon(id)}<span>${labels[row][i]}</span></button>`).join('')}<button class="back" data-calm-routine="${row}:2" aria-pressed="${s.routine[row]===2}">Skip this part</button></fieldset>`).join('')}</div><p>You can use your choices away from the screen. Skipping every part is fine too.</p>`;}
 app.innerHTML=`<div class="play-top"><button class="back" id="calmBack">← Our calm garden</button><span class="together-note">♧ Play together</span></div><section class="game-wrap friendly-play calm-play"><span class="eyebrow">${d.group.toUpperCase()} · YOUR WAY, YOUR PACE</span><h1>${d.title}</h1><p class="play-invitation">${senEscape(inv)}</p><div class="game-stage">${body}<div class="feedback" role="status" aria-live="polite">${senEscape(s.message)}</div><div class="calm-controls"><button class="secondary" id="calmStop">Stop / choose something else</button><button class="primary" id="calmFinish">Finish whenever you like →</button></div></div><details class="quiet-notes"><summary>A little tip for grown-ups</summary><p>${senEscape(d.skill)}</p><p>${senEscape(d.tip)}</p><p>Adult support is needed. Participation is optional; do not require stillness or a calm appearance. This app does not assess concentration, relaxation, breathing, or movement.</p></details><details class="quiet-notes"><summary>Try it away from the screen</summary><p>${senEscape(d.away)}</p></details></section>`;
 const bind=(id,fn)=>{const el=document.getElementById(id);if(el)el.onclick=fn;};calmNav();bind('calmBack',calmHome);bind('calmStop',calmHome);bind('calmFinish',calmFinish);
 document.querySelectorAll('[data-calm-choice]').forEach(b=>b.onclick=()=>{s.selected=+b.dataset.calmChoice;s.found=false;s.message='';calmRender('choice:'+s.selected);});bind('calmCheck',()=>{s.found=s.selected===calmModel(s).answer;s.message=s.found?'You found our clue. Another try, a pause, or all done?':'Let’s compare together. You can change your choice or ask for help.';calmRender('calmCheck');});bind('calmHelp',()=>{s.help=true;s.message='Here is the matching picture. Explore the clue together.';calmRender('calmHelp');});bind('calmFewer',()=>{s.fewer=!s.fewer;s.selected=null;s.found=false;s.message='';calmRender('calmFewer');});bind('calmTry',()=>{s.step++;s.selected=null;s.found=false;s.help=false;s.message='';calmRender('calmTry');});
 document.querySelectorAll('[data-calm-home]').forEach(b=>b.onclick=()=>{s.path++;calmRender(s.path<3?'home:'+s.path:'calmPathAgain');});bind('calmPathAgain',()=>{s.path=0;calmRender('home:0');});
 document.querySelectorAll('[data-calm-open]').forEach(b=>b.onclick=()=>{s.selected=+b.dataset.calmOpen;s.message=d.mode==='comfort'?['Let’s find a comfortable resting place.','Choose a familiar comfortable movement or view.','Invite company or use your usual communication support.'][s.selected]:'Explore your idea together. Point, sign, speak, or use AAC. There is no right answer.';calmRender('open:'+s.selected);});bind('calmWatchBreath',()=>{s.watch=!s.watch;s.breath=false;calmRender('calmWatchBreath');});bind('calmFlower',()=>{s.breath=!s.breath;calmRender('calmFlower');});bind('calmPause',()=>{s.paused=!s.paused;calmRender('calmPause');});bind('calmHands',()=>{s.step++;calmRender('calmHands');});bind('calmWatch',()=>{s.watch=!s.watch;calmRender('calmWatch');});bind('calmSeat',()=>{s.seated=true;calmRender('calmSeat');});bind('calmStand',()=>{s.seated=false;calmRender('calmStand');});
 document.querySelectorAll('[data-calm-routine]').forEach(b=>b.onclick=()=>{const [r,i]=b.dataset.calmRoutine.split(':').map(Number);s.routine[r]=i;calmRender('routine:'+b.dataset.calmRoutine);});
 if(focus){let el=focus.startsWith('choice:')?document.querySelector(`[data-calm-choice="${focus.slice(7)}"]`):focus.startsWith('open:')?document.querySelector(`[data-calm-open="${focus.slice(5)}"]`):focus.startsWith('home:')?document.querySelector(`[data-calm-home="${focus.slice(5)}"]`):focus.startsWith('routine:')?document.querySelector(`[data-calm-routine="${focus.slice(8)}"]`):document.getElementById(focus);if(el&&!el.disabled)el.focus({preventScroll:true});}
}
function calmFinish(){const s=calmState,d=calmActivities[s.index];calmProgress[s.index]={explored:true};calmSave();app.innerHTML=`<section class="game-wrap friendly-play calm-play"><div class="completion-friend">${friendlyMascot()}</div><h1>A little moment for you.</h1><p>Thank you for exploring your way. You do not have to feel calmer or finish a movement.</p><p>${senEscape(d.away)}</p><div class="calm-controls"><button class="secondary" id="calmAgain">Explore this again</button><button class="primary" id="calmReturn">Choose another activity →</button></div><p class="micro">Explored, not assessed. No concentration or relaxation score is saved.</p></section>`;calmNav();document.querySelector('#calmAgain').onclick=()=>calmOpen(s.index);document.querySelector('#calmReturn').onclick=calmHome;window.scrollTo(0,0);}
libraryHome();
